+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>Vegan Ramen</title>
+  <style>
+    html,
+    body {
+      width: 100%;
+      height: 100%;
+      margin: 0;
+      overflow: hidden;
+      background: #050607;
+    }
+
+    body {
+      min-height: 100svh;
+    }
+
+    canvas {
+      display: block;
+      width: 100vw;
+      height: 100svh;
+      touch-action: none;
+    }
+
+    @media (prefers-reduced-motion: reduce) {
+      canvas {
+        scroll-behavior: auto;
+      }
+    }
+  </style>
+</head>
+<body>
+  <canvas id="scene" aria-hidden="true"></canvas>
+  <script>
+    (() => {
+      const canvas = document.getElementById('scene');
+      const ctx = canvas.getContext('2d', { alpha: false });
+      const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
+      const pointer = { x: 0, y: 0, tx: 0, ty: 0, active: false };
+      const seed = mulberry32(42);
+      const TWO_PI = Math.PI * 2;
+      let w = 0;
+      let h = 0;
+      let dpr = 1;
+      let frame = 0;
+      let raf = 0;
+
+      const steam = Array.from({ length: 34 }, (_, i) => ({
+        offset: seed() * TWO_PI,
+        x: (seed() - 0.5) * 0.76,
+        y: seed(),
+        speed: 0.22 + seed() * 0.45,
+        sway: 0.18 + seed() * 0.36,
+        width: 0.006 + seed() * 0.012,
+        lift: 0.33 + seed() * 0.31,
+        alpha: 0.16 + seed() * 0.22
+      }));
+
+      const brothBubbles = Array.from({ length: 22 }, () => ({
+        x: (seed() - 0.5) * 0.73,
+        y: (seed() - 0.5) * 0.52,
+        r: 0.003 + seed() * 0.012,
+        phase: seed() * TWO_PI,
+        drift: seed() * 0.014
+      }));
+
+      const noodleLines = Array.from({ length: 21 }, (_, i) => ({
+        y: -0.18 + i * 0.019 + (seed() - 0.5) * 0.013,
+        amp: 0.014 + seed() * 0.024,
+        phase: seed() * TWO_PI,
+        length: 0.44 + seed() * 0.31,
+        x: (seed() - 0.5) * 0.18
+      }));
+
+      const sesame = Array.from({ length: 38 }, () => ({
+        x: (seed() - 0.5) * 0.72,
+        y: (seed() - 0.5) * 0.46,
+        a: seed() * TWO_PI,
+        s: 0.004 + seed() * 0.006
+      }));
+
+      function mulberry32(a) {
+        return function random() {
+          let t = a += 0x6D2B79F5;
+          t = Math.imul(t ^ t >>> 15, t | 1);
+          t ^= t + Math.imul(t ^ t >>> 7, t | 61);
+          return ((t ^ t >>> 14) >>> 0) / 4294967296;
+        };
+      }
+
+      function resize() {
+        dpr = Math.min(window.devicePixelRatio || 1, 2);
+        w = Math.max(1, window.innerWidth);
+        h = Math.max(1, window.innerHeight);
+        canvas.width = Math.round(w * dpr);
+        canvas.height = Math.round(h * dpr);
+        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
+        pointer.tx = pointer.x = pointer.tx || 0;
+        pointer.ty = pointer.y = pointer.ty || 0;
+        draw(performance.now() * 0.001, true);
+      }
+
+      function updatePointer(clientX, clientY) {
+        pointer.tx = (clientX / w - 0.5) * 2;
+        pointer.ty = (clientY / h - 0.5) * 2;
+        pointer.active = true;
+        if (reduceMotion.matches) {
+          pointer.x = pointer.tx;
+          pointer.y = pointer.ty;
+          draw(performance.now() * 0.001, true);
+        }
+      }
+
+      function leavePointer() {
+        pointer.tx = 0;
+        pointer.ty = 0;
+        pointer.active = false;
+        if (reduceMotion.matches) {
+          pointer.x = 0;
+          pointer.y = 0;
+          draw(performance.now() * 0.001, true);
+        }
+      }
+
+      function ellipsePath(cx, cy, rx, ry) {
+        ctx.beginPath();
+        ctx.ellipse(cx, cy, rx, ry, 0, 0, TWO_PI);
+      }
+
+      function roundedRect(x, y, width, height, radius) {
+        const r = Math.min(radius, width * 0.5, height * 0.5);
+        ctx.beginPath();
+        ctx.moveTo(x + r, y);
+        ctx.arcTo(x + width, y, x + width, y + height, r);
+        ctx.arcTo(x + width, y + height, x, y + height, r);
+        ctx.arcTo(x, y + height, x, y, r);
+        ctx.arcTo(x, y, x + width, y, r);
+        ctx.closePath();
+      }
+
+      function setShadow(color, blur, x = 0, y = 0) {
+        ctx.shadowColor = color;
+        ctx.shadowBlur = blur;
+        ctx.shadowOffsetX = x;
+        ctx.shadowOffsetY = y;
+      }
+
+      function clearShadow() {
+        ctx.shadowColor = 'transparent';
+        ctx.shadowBlur = 0;
+        ctx.shadowOffsetX = 0;
+        ctx.shadowOffsetY = 0;
+      }
+
+      function drawBackground(t, sceneScale, cx, cy) {
+        const warmthX = cx + pointer.x * sceneScale * 0.08;
+        const warmthY = cy - sceneScale * 0.06 + pointer.y * sceneScale * 0.04;
+        const base = ctx.createLinearGradient(0, 0, 0, h);
+        base.addColorStop(0, '#040507');
+        base.addColorStop(0.42, '#080909');
+        base.addColorStop(1, '#010202');
+        ctx.fillStyle = base;
+        ctx.fillRect(0, 0, w, h);
+
+        const heat = ctx.createRadialGradient(warmthX, warmthY, 0, warmthX, warmthY, sceneScale * 1.25);
+        heat.addColorStop(0, 'rgba(255, 130, 45, 0.27)');
+        heat.addColorStop(0.2, 'rgba(202, 71, 26, 0.16)');
+        heat.addColorStop(0.58, 'rgba(54, 22, 15, 0.23)');
+        heat.addColorStop(1, 'rgba(0, 0, 0, 0)');
+        ctx.fillStyle = heat;
+        ctx.fillRect(0, 0, w, h);
+
+        const coolEdge = ctx.createRadialGradient(cx, cy, sceneScale * 0.25, cx, cy, sceneScale * 1.28);
+        coolEdge.addColorStop(0, 'rgba(0,0,0,0)');
+        coolEdge.addColorStop(0.64, 'rgba(0,0,0,0.08)');
+        coolEdge.addColorStop(1, 'rgba(0,0,0,0.78)');
+        ctx.fillStyle = coolEdge;
+        ctx.fillRect(0, 0, w, h);
+
+        const floor = ctx.createRadialGradient(cx, cy + sceneScale * 0.34, 0, cx, cy + sceneScale * 0.34, sceneScale * 0.68);
+        floor.addColorStop(0, 'rgba(255, 98, 39, 0.17)');
+        floor.addColorStop(0.52, 'rgba(97, 39, 23, 0.11)');
+        floor.addColorStop(1, 'rgba(0, 0, 0, 0)');
+        ctx.fillStyle = floor;
+        ctx.fillRect(0, 0, w, h);
+
+        const pulse = reduceMotion.matches ? 0 : Math.sin(t * 1.25) * 0.035;
+        const ember = ctx.createRadialGradient(cx, cy + sceneScale * 0.16, 0, cx, cy + sceneScale * 0.16, sceneScale * 0.52);
+        ember.addColorStop(0, `rgba(255, 160, 72, ${0.05 + pulse})`);
+        ember.addColorStop(1, 'rgba(255, 160, 72, 0)');
+        ctx.fillStyle = ember;
+        ctx.fillRect(0, 0, w, h);
+      }
+
+      function drawSteam(t, sceneScale, cx, cy, bowlRx, brothRy) {
+        ctx.save();
+        ctx.globalCompositeOperation = 'screen';
+        ctx.lineCap = 'round';
+        const mouseDrift = pointer.x * sceneScale * 0.035;
+        const top = cy - brothRy * 0.8;
+        const reduced = reduceMotion.matches;
+
+        steam.forEach((p) => {
+          const localTime = reduced ? p.offset : t * p.speed + p.offset;
+          const rise = reduced ? p.y : (p.y + t * p.speed * 0.05) % 1;
+          const startX = cx + p.x * bowlRx + mouseDrift * (0.4 + rise);
+          const startY = top - rise * sceneScale * p.lift;
+          const length = sceneScale * (0.12 + p.lift * 0.28);
+          const sway = Math.sin(localTime * 1.6) * p.sway * sceneScale * 0.14 + mouseDrift;
+          const width = Math.max(1, sceneScale * p.width * (1 - rise * 0.35));
+          const opacity = p.alpha * Math.pow(1 - rise, 0.9) * (reduced ? 0.42 : 1);
