+        clearShadow();
+        ctx.restore();
+      }
+
+      function drawToppings(cx, cy, bowlRx, brothRy, sceneScale, t) {
+        const bob = reduceMotion.matches ? 0 : Math.sin(t * 1.4) * sceneScale * 0.004;
+        drawMushrooms(cx - bowlRx * 0.24, cy - brothRy * 0.05 + bob, sceneScale, -0.14);
