+        drawSesame(cx, cy, sceneScale);
+      }
+
+      function drawMushrooms(x, y, sceneScale, angle) {
+        ctx.save();
+        ctx.translate(x, y);
+        ctx.rotate(angle);
+        setShadow('rgba(34, 11, 5, 0.35)', sceneScale * 0.02, 0, sceneScale * 0.006);
+        ctx.fillStyle = '#8a5132';
+        ellipsePath(0, -sceneScale * 0.02, sceneScale * 0.11, sceneScale * 0.052);
+        ctx.fill();
+        ctx.fillStyle = '#d9ac77';
+        ellipsePath(0, sceneScale * 0.008, sceneScale * 0.085, sceneScale * 0.038);
+        ctx.fill();
+        ctx.strokeStyle = 'rgba(77, 35, 20, 0.45)';
+        ctx.lineWidth = Math.max(1, sceneScale * 0.004);
+        for (let i = -2; i <= 2; i++) {
+          ctx.beginPath();
+          ctx.moveTo(0, sceneScale * 0.008);
+          ctx.lineTo(i * sceneScale * 0.026, sceneScale * 0.035);
+          ctx.stroke();
+        }
+        clearShadow();
+        ctx.restore();
+      }
+
+      function drawTofu(x, y, sceneScale) {
+        const size = sceneScale * 0.068;
+        [
+          [-0.74, 0.12, -0.22],
+          [0.14, -0.1, 0.16],
+          [0.84, 0.17, -0.08]
+        ].forEach(([dx, dy, rot]) => {
+          ctx.save();
+          ctx.translate(x + dx * size, y + dy * size);
+          ctx.rotate(rot);
+          setShadow('rgba(48, 18, 5, 0.3)', sceneScale * 0.018, 0, sceneScale * 0.006);
+          roundedRect(-size * 0.45, -size * 0.34, size * 0.9, size * 0.68, size * 0.08);
+          const tofu = ctx.createLinearGradient(-size * 0.45, -size * 0.34, size * 0.45, size * 0.34);
+          tofu.addColorStop(0, '#fff0b4');
+          tofu.addColorStop(0.52, '#ebc772');
+          tofu.addColorStop(1, '#b66e32');
+          ctx.fillStyle = tofu;
+          ctx.fill();
+          ctx.strokeStyle = 'rgba(88, 42, 16, 0.3)';
+          ctx.lineWidth = Math.max(1, sceneScale * 0.003);
+          ctx.stroke();
+          clearShadow();
+          ctx.restore();
+        });
+      }
+
+      function drawBokChoy(x, y, sceneScale) {
+        ctx.save();
+        ctx.translate(x, y);
+        ctx.rotate(0.08);
+        setShadow('rgba(18, 55, 20, 0.28)', sceneScale * 0.018, 0, sceneScale * 0.006);
+        for (let i = -2; i <= 2; i++) {
+          const angle = i * 0.2;
+          ctx.save();
+          ctx.rotate(angle);
+          const leaf = ctx.createRadialGradient(0, -sceneScale * 0.06, 0, 0, -sceneScale * 0.04, sceneScale * 0.16);
