+          ctx.strokeStyle = 'rgba(226, 245, 160, 0.38)';
+          ctx.lineWidth = Math.max(1, sceneScale * 0.004);
+          ctx.beginPath();
+          ctx.moveTo(0, sceneScale * 0.055);
+          ctx.lineTo(0, -sceneScale * 0.12);
+          ctx.stroke();
+          ctx.restore();
+        }
+        ctx.fillStyle = '#e9edb9';
+        roundedRect(-sceneScale * 0.028, -sceneScale * 0.02, sceneScale * 0.056, sceneScale * 0.13, sceneScale * 0.025);
+        ctx.fill();
+        clearShadow();
+        ctx.restore();
+      }
+
+      function drawScallions(cx, cy, bowlRx, brothRy, sceneScale) {
+        ctx.save();
+        ellipsePath(cx, cy, bowlRx * 0.75, brothRy * 0.63);
+        ctx.clip();
+        ctx.lineCap = 'round';
+        for (let i = 0; i < 18; i++) {
+          const a = i * 2.399;
+          const r = (0.1 + (i % 7) * 0.075) * bowlRx;
+          const x = cx + Math.cos(a) * r + pointer.x * sceneScale * 0.006;
+          const y = cy + Math.sin(a * 1.37) * r * 0.42;
+          const length = sceneScale * (0.035 + (i % 5) * 0.006);
+          ctx.save();
+          ctx.translate(x, y);
+          ctx.rotate(a + Math.PI * 0.5);
+          ctx.strokeStyle = i % 2 ? '#b4ec65' : '#68bf3f';
+          ctx.lineWidth = Math.max(2, sceneScale * 0.007);
+          ctx.beginPath();
+          ctx.moveTo(-length * 0.5, 0);
+          ctx.lineTo(length * 0.5, 0);
+          ctx.stroke();
+          ctx.restore();
+        }
+        ctx.restore();
+      }
+
+      function drawSesame(cx, cy, sceneScale) {
+        ctx.save();
+        ctx.fillStyle = 'rgba(255, 224, 154, 0.78)';
+        sesame.forEach((s) => {
+          ctx.save();
+          ctx.translate(cx + s.x * sceneScale, cy + s.y * sceneScale * 0.62);
+          ctx.rotate(s.a);
+          ellipsePath(0, 0, sceneScale * s.s * 1.7, sceneScale * s.s * 0.75);
+          ctx.fill();
+          ctx.restore();
+        });
+        ctx.restore();
+      }
+
+      function drawBowl(cx, cy, bowlRx, bowlRy, sceneScale) {
+        const bottomY = cy + bowlRy * 0.46;
+        setShadow('rgba(0, 0, 0, 0.72)', sceneScale * 0.07, 0, sceneScale * 0.055);
