+        ctx.fillStyle = 'rgba(0,0,0,0.58)';
+        ctx.fill();
+        clearShadow();
+
+        ctx.beginPath();
+        ctx.moveTo(cx - bowlRx * 0.88, cy - bowlRy * 0.08);
+        ctx.bezierCurveTo(cx - bowlRx * 0.78, cy + bowlRy * 0.72, cx - bowlRx * 0.35, cy + bowlRy * 1.03, cx, cy + bowlRy * 1.05);
+        ctx.bezierCurveTo(cx + bowlRx * 0.35, cy + bowlRy * 1.03, cx + bowlRx * 0.78, cy + bowlRy * 0.72, cx + bowlRx * 0.88, cy - bowlRy * 0.08);
