+        const ceramic = ctx.createLinearGradient(cx, cy - bowlRy * 0.12, cx, cy + bowlRy * 1.04);
+        ceramic.addColorStop(0, '#222b2e');
+        ceramic.addColorStop(0.26, '#151b1d');
+        ceramic.addColorStop(0.62, '#0b0f10');
+        ceramic.addColorStop(1, '#050606');
+        ctx.fillStyle = ceramic;
+        ctx.fill();
+
+        const sideGlow = ctx.createRadialGradient(cx - bowlRx * 0.12, cy + bowlRy * 0.18, 0, cx, cy + bowlRy * 0.36, bowlRx * 0.96);
+        sideGlow.addColorStop(0, 'rgba(255, 112, 44, 0.2)');
+        sideGlow.addColorStop(0.45, 'rgba(255, 93, 37, 0.08)');
+        sideGlow.addColorStop(1, 'rgba(0, 0, 0, 0)');
+        ctx.fillStyle = sideGlow;
+        ctx.fill();
+
+        ellipsePath(cx, cy - bowlRy * 0.1, bowlRx * 0.93, bowlRy * 0.27);
+        setShadow('rgba(255, 121, 45, 0.34)', sceneScale * 0.035);
+        ctx.strokeStyle = '#2f3b3c';
+        ctx.lineWidth = Math.max(7, sceneScale * 0.025);
+        ctx.stroke();
+        clearShadow();
+
+        ellipsePath(cx, cy - bowlRy * 0.1, bowlRx * 0.88, bowlRy * 0.23);
+        ctx.strokeStyle = 'rgba(230, 244, 229, 0.2)';
+        ctx.lineWidth = Math.max(1, sceneScale * 0.004);
+        ctx.stroke();
+
+        const shine = ctx.createLinearGradient(cx - bowlRx * 0.75, cy, cx + bowlRx * 0.48, cy + bowlRy * 0.84);
+        shine.addColorStop(0, 'rgba(255, 255, 255, 0.17)');
+        shine.addColorStop(0.22, 'rgba(255, 255, 255, 0.03)');
+        shine.addColorStop(0.56, 'rgba(255, 113, 44, 0.06)');
+        shine.addColorStop(1, 'rgba(255, 255, 255, 0)');
