+      }
+
+      function draw(t, forceStill = false) {
+        const still = reduceMotion.matches || forceStill;
+        const eased = still ? 1 : 0.075;
+        pointer.x += (pointer.tx - pointer.x) * eased;
+        pointer.y += (pointer.ty - pointer.y) * eased;
+
